create table if not exists public.menu_items (id uuid primary key default gen_random_uuid(), name text not null, category text not null, description text, price numeric(10,2) not null, emoji text, available boolean default true, created_at timestamptz default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, customer_name text not null, phone text not null, order_mode text not null, status text not null default 'NEW', total numeric(10,2) not null default 0, created_at timestamptz default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid references public.orders(id) on delete cascade, menu_item_id uuid references public.menu_items(id), item_name text not null, quantity integer not null, unit_price numeric(10,2) not null);
create table if not exists public.inventory_items (id uuid primary key default gen_random_uuid(), name text not null, unit text not null, stock numeric(12,2) default 0, reorder_level numeric(12,2) default 0, updated_at timestamptz default now());
create table if not exists public.catering_requests (id uuid primary key default gen_random_uuid(), customer_name text not null, phone text not null, event_date date, guests integer, event_type text, notes text, status text default 'NEW', created_at timestamptz default now());
alter table public.menu_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.inventory_items enable row level security; alter table public.catering_requests enable row level security;
-- Add authenticated staff policies and customer-specific order policies before production writes. Never put a service-role key in frontend code.